const input = $input.first()?.json || {};

const job_id = input.job_id || ('job_recovered_' + Date.now().toString(36));
const intent = input.intent || 'search_private';

let entities = input.entities;
let attempts = 0;
while (typeof entities === 'string' && attempts < 3) {
  try { entities = JSON.parse(entities); } catch(e) { entities = {}; break; }
  attempts++;
}
entities = entities || {};

const service = entities.service || 'услуга';
const region = entities.region || 'Россия';
const budget_min = entities.budget_min || 0;
const budget_max = entities.budget_max || 999999999;

if (service === 'услуга' && !input.intent) {
  throw new Error("Критическая ошибка: Данные не дошли до узла.");
}

const queries = [];
const isClientSearch = intent === 'search_private';

if (isClientSearch) {
  const sourceTargets = [
    { q: `${service} ${region} avito.ru`, platform: 'avito' },
    { q: `${service} ${region} youla.ru`, platform: 'youla' },
    { q: `${service} ищу ${region} vk.com`, platform: 'vk' },
    { q: `${service} ${region} t.me заказ`, platform: 'telegram' },
    { q: `${service} ${region} poisk-pro.ru`, platform: 'poisk-pro' },
    { q: `${service} ${region} pro.petrovich.ru`, platform: 'petrovich' }
  ];
  for (const t of sourceTargets) {
    queries.push({ json: { query: t.q, source_platform: t.platform, region, job_id, service, budget_min, budget_max } });
  }
  const clientPlatforms = [
    `"нужен ${service}" ${region}`,
    `"ищу ${service}" ${region}`,
    `"требуется ${service}" ${region}`,
    `"нужен мастер по ${service}" ${region}`,
    `"посоветуйте ${service}" ${region}`,
    `${service} ${region} Авито`,
    `${service} ${region} Юла`,
    `${service} ${region} частное лицо ищу`,
    `${service} ${region} заказать`,
    `${service} ${region} частный заказ`
  ];
  for (const query of clientPlatforms) {
    queries.push({ json: { query, source_platform: 'general', region, job_id, service, budget_min, budget_max } });
  }
} else {
  const b2bPlatforms = [
    `${service} ${region} Авито`,
    `${service} ${region} Юла`,
    `${service} ${region} Profi`,
    `${service} ${region} YouDo`,
    `${service} ищу ${region} ВКонтакте`,
    `${service} ${region} Telegram заказ`,
    `${service} ${region} частное лицо`,
    `${service} ${region} ищу мастера`,
    `${service} ${region} под ключ`,
    `${service} ${region} срочно`,
    `${service} ${region} услуги`,
    `${service} ${region} цена`,
    `${service} ${region} частный мастер`,
    `${service} ${region} заказать`
  ];
  for (const query of b2bPlatforms) {
    queries.push({ json: { query, source_platform: 'general', region, job_id, service, budget_min, budget_max } });
  }
}

// DIAG V2: Initialize accumulator for in-scope jobs
(function() {
  try {
    const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/ё/g, 'е').replace(/[‐‑‒–—−]/g, '-');
    const diagInScope = intent === 'search_private' && normalize(service).includes('вентиляц') && (/(^|[^а-яa-z0-9])спб([^а-яa-z0-9]|$)/u.test(normalize(region)) || normalize(region).includes('петербург'));
    if (!diagInScope) return;
    const diagKey = 'wf2_diag_v2_' + job_id;
    const sd = $getWorkflowStaticData('global');
    const now = Date.now();
    for (const k of Object.keys(sd)) {
      if (k.startsWith('wf2_diag_v2_') && sd[k]?.ts && (now - sd[k].ts > 86400000)) {
        delete sd[k];
      }
    }
    sd[diagKey] = { ts: now, queryCount: queries.length, queriesByPlatform: {} };
    for (const q of queries) {
      const p = q.json.source_platform || 'unknown';
      sd[diagKey].queriesByPlatform[p] = (sd[diagKey].queriesByPlatform[p] || 0) + 1;
    }
  } catch(e) { /* fail-open */ }
})();

return queries;

// TEMP Finalize WF2 Funnel V2 — reads transient accumulator, builds compact diagnostic
// Runs when Loop Queries completes (output 0 = DONE).
// Fail-open: any error returns original items unchanged with emit=false.

try {
  const normalize = (value) => String(value ?? '').trim().toLowerCase().replace(/ё/g, 'е').replace(/[‐‑‒–—−]/g, '-');
  const items = $input.all();
  const firstItem = (items && items.length > 0) ? (items[0].json || {}) : {};

  let intent = '', service = '', region = '', jobId = '';
  try {
    const triggerData = $('Trigger').first().json;
    intent = triggerData.intent || '';
    jobId = triggerData.job_id || '';
    let entities = triggerData.entities;
    let attempts = 0;
    while (typeof entities === 'string' && attempts < 3) {
      try { entities = JSON.parse(entities); } catch(e) { entities = {}; break; }
      attempts++;
    }
    entities = entities || {};
    service = entities.service || '';
    region = entities.region || '';
  } catch(e) {}

  if (!service || !region) {
    service = firstItem.service || service;
    region = firstItem.region || region;
  }
  if (!jobId) jobId = firstItem.job_id || '';

  intent = normalize(intent);
  service = normalize(service);
  region = normalize(region);

  const inScope = intent === 'search_private' && service.includes('вентиляц') && (/(^|[^а-яa-z0-9])спб([^а-яa-z0-9]|$)/u.test(region) || region.includes('петербург'));

  let emit = false;
  let diagMessage = '';

  if (inScope) {
    const diagKey = 'wf2_diag_v2_' + jobId;
    const sd = $getWorkflowStaticData('global');
    const acc = sd[diagKey];

    if (acc) {
      const lines = ['TEMP WF2 FUNNEL DIAGNOSTIC V2'];
      lines.push('Job: ' + jobId);
      lines.push('Intent: ' + intent + ' | Svc: ' + service + ' | Region: ' + region);
      lines.push('Queries: ' + (acc.queryCount || 0));
      if (acc.queriesByPlatform) {
        const plat = Object.entries(acc.queriesByPlatform).map(function(e) { return e[0] + ':' + e[1]; }).join(' ');
        lines.push('ByPlatform: ' + plat);
      }
      lines.push('SerpOrganic: ' + (acc.serperOrganicTotal || 0) + ' | URL: ' + (acc.extractedUrlTotal || 0));
      lines.push('ClassIn: ' + (acc.classificationInput || 0) + ' D:' + (acc.demandCount || 0) + ' S:' + (acc.supplyCount || 0) + ' A:' + (acc.ambiguousCount || 0));
      lines.push('Keep: ' + (acc.keepCount || 0) + ' | Reject: ' + (acc.rejectCount || 0));
      if (acc.reasonCodes) lines.push('Codes: ' + JSON.stringify(acc.reasonCodes));
      lines.push('FltPass: ' + (acc.filterEmptyPassed || 0) + ' | LoopUrl: ' + (acc.loopUrlsEntered || 0));
      lines.push('FCAtt: ' + (acc.firecrawlAttempted || 0) + ' | FCUsable: ' + (acc.firecrawlUsable || 0));
      lines.push('CntOut: ' + (acc.extractContactsOutput || 0) + ' | WithCnt: ' + (acc.contactPresenceCount || 0));
      lines.push('AppendOK: ' + (acc.appendLeadSuccessOutput || 0));

      diagMessage = lines.join('\n');
      if (diagMessage.length > 3500) diagMessage = diagMessage.slice(0, 3500);

      delete sd[diagKey];
      emit = true;
    } else {
      diagMessage = 'TEMP WF2 FUNNEL DIAGNOSTIC V2\nJob: ' + jobId + '\nStatus: INSTRUMENTATION STATE MISSING';
      emit = true;
    }
  }

  return items.map(function(item) {
    return { json: Object.assign({}, item.json, { _temp_wf2_diag_v1_emit: emit, _temp_wf2_diag_v1_message: diagMessage }) };
  });
} catch(e) {
  return $input.all();
}

const item = $input.first();
if (!item || !item.json) return [{ json: { skip: true } }];
const serperData = item.json;
const query =
  serperData.query ||
  serperData.searchParameters?.q ||
  serperData.serperResult?.searchParameters?.q;
if (!query) {
  throw new Error("Extract URLs: required query context is missing");
}
let job_id = serperData.job_id || '';
if (!job_id) {
  try {
    job_id = $('Trigger').first().json.job_id || '';
  } catch(e) {}
}
if (!job_id) {
  throw new Error("Extract URLs: required job_id context is missing");
}
const source_platform = serperData.source_platform || 'general';
const organic = Array.isArray(serperData.organic)
  ? serperData.organic
  : Array.isArray(serperData.serperResult?.organic)
    ? serperData.serperResult.organic
    : [];
const SOURCE_TARGETED = new Set(['avito', 'youla', 'vk', 'telegram', 'poisk-pro', 'petrovich']);
const isSourceTargeted = SOURCE_TARGETED.has(source_platform);
const limit = isSourceTargeted ? 10 : 3;
const topN = organic.slice(0, limit);
const results = [];
for (const entry of topN) {
  if (!entry.link) continue;
  results.push({
    json: {
      url: entry.link,
      title: entry.title || '',
      snippet: entry.snippet || '',
      source_platform,
      query,
      job_id
    }
  });
}

// DIAG V2: record Serper stats
(function() {
  try {
    const diagKey = 'wf2_diag_v2_' + job_id;
    const sd = $getWorkflowStaticData('global');
    if (sd[diagKey]) {
      sd[diagKey].serperOrganicTotal = (sd[diagKey].serperOrganicTotal || 0) + organic.length;
      sd[diagKey].extractedUrlTotal = (sd[diagKey].extractedUrlTotal || 0) + results.length;
      sd[diagKey].ts = Date.now();
    }
  } catch(e) { /* fail-open */ }
})();

return results.length > 0 ? results : [{ json: { skip: true } }];

// ── Classify Private Candidates v5 zone rules ──
// Deterministic DEMAND/SUPPLY/AMBIGUOUS classification for search_private.
// Non-search_private items passthrough unchanged.
// SUPPLY candidates are rejected before Firecrawl.
// v5: added Profi/Youla host-zone predicates to close R06_DEFAULT gap.
// v5.1: added Poisk-Pro / ProPetrovich concrete-order DEMAND predicates.

const classificationVersion = "private_rules_v5";
const classifierBuildId = "v5_zone_rules_001";

// ── helpers (pure string parsers — no new URL()) ──
function getIntent(item) {
  if (item.json && item.json.intent) return item.json.intent;
  try {
    const ti = $('Trigger').first();
    if (ti && ti.json && ti.json.intent) return ti.json.intent;
  } catch(e) {}
  return '';
}
function hostname(url) {
  if (!url || typeof url !== 'string') return '';
  let s = url.trim().toLowerCase();
  const schemeIdx = s.indexOf('://');
  if (schemeIdx !== -1) s = s.slice(schemeIdx + 3);
  const slashIdx = s.indexOf('/');
  if (slashIdx !== -1) s = s.slice(0, slashIdx);
  const colonIdx = s.lastIndexOf(':');
  if (colonIdx !== -1) s = s.slice(0, colonIdx);
  if (s.startsWith('www.')) s = s.slice(4);
  return s;
}
function pathname(url) {
  if (!url || typeof url !== 'string') return '';
  let s = url.trim().toLowerCase();
  const schemeIdx = s.indexOf('://');
  if (schemeIdx !== -1) s = s.slice(schemeIdx + 3);
  const slashIdx = s.indexOf('/');
  if (slashIdx === -1) return '/';
  s = s.slice(slashIdx);
  const qIdx = s.indexOf('?');
  if (qIdx !== -1) s = s.slice(0, qIdx);
  const fIdx = s.indexOf('#');
  if (fIdx !== -1) s = s.slice(0, fIdx);
  return s;
}
function hasServicePath(url) {
  const p = pathname(url);
  return p.includes('/uslugi/') ||
         p.includes('/promo/') ||
         p.includes('/service/') ||
         p.includes('/remont/') ||
         p.includes('montazh') ||
         p.includes('montaj') ||
         p.includes('ventil') ||
         p.includes('ventilyats');
}
function hasServiceContext(text) {
  return text.includes('монтаж') ||
         text.includes('вентиляц') ||
         text.includes('ventil') ||
         text.includes('ventilyats');
}
function isProfiHost(url) {
  const h = hostname(url);
  return h === 'profi.ru' || h.endsWith('.profi.ru');
}
function isYoulaHost(url) {
  const h = hostname(url);
  return h === 'youla.ru' || h.endsWith('.youla.ru');
}
function isProfiServiceZone(url) {
  if (!isProfiHost(url)) return false;
  const p = pathname(url);
  return /^\/geo-[^/]+\/remont(?:\/|$)/.test(p);
}
function isYoulaServiceZone(url, lower) {
  if (!isYoulaHost(url)) return false;
  const p = pathname(url);
  return p.includes('/uslugi/') && hasServiceContext(lower);
}

// ── v5.1: Source-aware concrete-order DEMAND predicates ──
function isPoiskProHost(url) {
  const h = hostname(url);
  return h === 'poisk-pro.ru' || h.endsWith('.poisk-pro.ru');
}
function isPetrovichHost(url) {
  const h = hostname(url);
  return h === 'pro.petrovich.ru' || h.endsWith('.pro.petrovich.ru');
}
function isPoiskProOrder(url) {
  if (!isPoiskProHost(url)) return false;
  const p = pathname(url);
  return /^\/order\/\d+(?:\/|$)/.test(p);
}
function isPetrovichOrder(url) {
  if (!isPetrovichHost(url)) return false;
  const p = pathname(url);
  const hasOrdersPath = p.includes('/orders/') || p.includes('/orders-btob/');
  if (!hasOrdersPath) return false;
  return /\/\d+$/.test(p);
}

// ── SUPPLY rules (ordered by precedence) ──

function isR00ServiceProviderPage(url, lower) {
  if (isProfiServiceZone(url)) return true;
  if (isYoulaServiceZone(url, lower)) return true;
  if (!hasServicePath(url)) return false;
  return lower.includes('под ключ') ||
         lower.includes('компания') ||
         lower.includes('стоимость') ||
         lower.includes('цены') ||
         lower.includes('скидкой') ||
         lower.includes('специалиста готовы') ||
         lower.includes('специалисты готовы') ||
         lower.includes('найдите частного') ||
         lower.includes('исполнителей') ||
         lower.includes('платная доска объявлений') ||
         lower.includes('хотите установить') ||
         lower.includes('хотите купить');
}

function isR01MarketplacePromo(url, lower) {
  if (!isProfiHost(url)) return false;
  const p = pathname(url);
  if (!p.includes('/promo/')) return false;
  return lower.includes('специалиста готовы') ||
         lower.includes('специалисты готовы') ||
         lower.includes('найдите') ||
         lower.includes('скидкой') ||
         lower.includes('на нашем сайте') ||
         lower.includes('рубл') ||
         lower.includes('исполнителей');
}

function isR02ExecutorCatalog(lower) {
  const hasExecListing = lower.includes('исполнител');
  if (!hasExecListing) return false;
  return hasServiceContext(lower);
}

function isR03CompanyMarketing(lower) {
  if (!lower.includes('компания')) return false;
  return hasServiceContext(lower);
}

function isR04SelfPromotion(lower) {
  if (lower.includes('наша компания')) return true;
  if (lower.includes('принимает заказы') && !lower.includes('ищу')) return true;
  if (lower.includes('оказываем услуги')) return true;
  if (lower.includes('выполняем') && lower.includes('монтаж')) return true;
  if (lower.includes('бригада') && lower.includes('предлагает')) return true;
  if (lower.includes('звоните')) return true;
  if (lower.includes('оставить заявку') && (lower.includes('монтаж') || lower.includes('вентиляц'))) return true;
  return false;
}

function isR05Demand(url, lower) {
  const p = pathname(url);
  if (p.includes('/request/') || p.includes('/requests/')) return true;
  if (p.includes('/zayavk') || p.includes('/zakaz')) return true;
  if (lower.includes('ищу бригаду')) return true;
  if (lower.includes('нужна бригада')) return true;
  if (lower.includes('ищем исполнител')) return true;
  if (lower.includes('посоветуйте бригаду')) return true;
  if (lower.includes('поделитесь контактами')) return true;
  if (lower.includes('кто может сделать')) return true;
  if (lower.includes('ищем мастер')) return true;
  if (lower.includes('ищу мастер')) return true;
  if (lower.includes('заявки на субподряд')) return true;
  const hasReq = lower.includes('требуется') && (lower.includes('выполнить') || lower.includes('сделать'));
  const hasResources = lower.includes('расходники предоставим') ||
                       lower.includes('леса предоставим') ||
                       lower.includes('объемы внушительные');
  const hasRegion = lower.includes('регион:');
  const hasAddress = lower.includes('адрес:');
  const taskSignals = [hasReq, hasResources, hasRegion, hasAddress].filter(Boolean).length;
  if (taskSignals >= 2) return true;
  return false;
}

// ── debug build (v5 zone rules + v5.1 order predicates) ──
function buildDebug(url, title, snippet, idx) {
  const lower = (title + ' ' + snippet).toLowerCase();
  const path = pathname(url);
  const hsPath = hasServicePath(url);
  const hsCtx = hasServiceContext(lower);
  const ipHost = isProfiHost(url);
  const iyHost = isYoulaHost(url);
  const ipServiceZone = isProfiServiceZone(url);
  const iyServiceZone = isYoulaServiceZone(url, lower);
  const ippHost = isPoiskProHost(url);
  const ipvHost = isPetrovichHost(url);
  const ippOrder = isPoiskProOrder(url);
  const ipvOrder = isPetrovichOrder(url);
  const r00 = isR00ServiceProviderPage(url, lower);
  const r01 = isR01MarketplacePromo(url, lower);
  const r02 = isR02ExecutorCatalog(lower);
  const r03 = isR03CompanyMarketing(lower);
  const r04 = isR04SelfPromotion(lower);
  const r05 = isR05Demand(url, lower);
  let matchedRule = 'R06_DEFAULT';
  let matchedPrecedence = 6;
  if (ippOrder) { matchedRule = 'R05A_POISKPRO_ORDER'; matchedPrecedence = -1; }
  else if (ipvOrder) { matchedRule = 'R05B_PETROVICH_ORDER'; matchedPrecedence = -1; }
  else if (r00) { matchedRule = 'R00_SERVICE_PROVIDER_PAGE'; matchedPrecedence = 0; }
  else if (r01) { matchedRule = 'R01_MARKETPLACE_PROMO'; matchedPrecedence = 1; }
  else if (r02) { matchedRule = 'R02_EXECUTOR_CATALOG'; matchedPrecedence = 2; }
  else if (r03) { matchedRule = 'R03_COMPANY_MARKETING'; matchedPrecedence = 3; }
  else if (r04) { matchedRule = 'R04_SELF_PROMOTION'; matchedPrecedence = 4; }
  else if (r05) { matchedRule = 'R05_DEMAND'; matchedPrecedence = 5; }
  return {
    classifier_build_id: classifierBuildId,
    input_index: idx,
    url_raw_len: url.length,
    url_raw_preview: url.slice(0, 100),
    title_raw_len: title.length,
    title_raw_preview: title.slice(0, 100),
    snippet_raw_len: snippet.length,
    snippet_raw_preview: snippet.slice(0, 100),
    path_normalized: path,
    lower_preview: lower.slice(0, 150),
    predicates: {
      hasServicePath: hsPath,
      hasServiceContext: hsCtx,
      isProfiHost: ipHost,
      isYoulaHost: iyHost,
      isProfiServiceZone: ipServiceZone,
      isYoulaServiceZone: iyServiceZone,
      isPoiskProHost: ippHost,
      isPetrovichHost: ipvHost,
      isPoiskProOrder: ippOrder,
      isPetrovichOrder: ipvOrder,
      R00_SERVICE_PROVIDER_PAGE: r00,
      R01_MARKETPLACE_PROMO: r01,
      R02_EXECUTOR_CATALOG: r02,
      R03_COMPANY_MARKETING: r03,
      R04_SELF_PROMOTION: r04,
      R05_DEMAND: r05
    },
    matched_rule: matchedRule,
    matched_precedence: matchedPrecedence
  };
}

// ── classify (v5.1: concrete-order DEMAND rules checked BEFORE SUPPLY) ──
function classify(url, title, snippet) {
  const lower = (title + ' ' + snippet).toLowerCase();
  if (isPoiskProOrder(url))                     return { cls: 'DEMAND', codes: ['R05A_POISKPRO_ORDER'] };
  if (isPetrovichOrder(url))                     return { cls: 'DEMAND', codes: ['R05B_PETROVICH_ORDER'] };
  if (isR00ServiceProviderPage(url, lower))      return { cls: 'SUPPLY', codes: ['R00_SERVICE_PROVIDER_PAGE'] };
  if (isR01MarketplacePromo(url, lower))          return { cls: 'SUPPLY', codes: ['R01_MARKETPLACE_PROMO'] };
  if (isR02ExecutorCatalog(lower))                return { cls: 'SUPPLY', codes: ['R02_EXECUTOR_CATALOG'] };
  if (isR03CompanyMarketing(lower))               return { cls: 'SUPPLY', codes: ['R03_COMPANY_MARKETING'] };
  if (isR04SelfPromotion(lower))                  return { cls: 'SUPPLY', codes: ['R04_SELF_PROMOTION'] };
  if (isR05Demand(url, lower))                    return { cls: 'DEMAND', codes: ['R05_DEMAND'] };
  return { cls: 'AMBIGUOUS', codes: ['R06_DEFAULT'] };
}

// ── main ──
const inputItems = $input.all();
if (!inputItems || inputItems.length === 0) return [{ json: { skip: true } }];
const first = inputItems[0];
if (!first || !first.json) return [{ json: { skip: true } }];
if (first.json.skip === true) return inputItems;
const intent = getIntent(first);
if (intent !== 'search_private') return inputItems;

const query = first.json.query || '';
const jobId = first.json.job_id || '';
const sourcePlatform = first.json.source_platform || 'general';

const kept = [];
let supplyCount = 0;
const allSupplyCodes = new Set();
const rejectedDebugItems = [];

for (let idx = 0; idx < inputItems.length; idx++) {
  const item = inputItems[idx];
  if (!item || !item.json) continue;
  const url = (item.json.url || '').toString().trim();
  const title = (item.json.title || '').toString();
  const snippet = (item.json.snippet || '').toString();
  const result = classify(url, title, snippet);
  const debug = buildDebug(url, title, snippet, idx);
  if (result.cls === 'SUPPLY') {
    supplyCount++;
    result.codes.forEach(function(c) { allSupplyCodes.add(c); });
    rejectedDebugItems.push(Object.assign({}, debug, { final_candidate_class: 'SUPPLY', final_candidate_decision: 'REJECT' }));
  } else {
    debug.final_candidate_class = result.cls;
    debug.final_candidate_decision = 'KEEP';
    kept.push({
      json: Object.assign({}, item.json, {
        candidate_class: result.cls,
        candidate_decision: 'KEEP',
        classification_version: classificationVersion,
        classification_reason_codes: result.codes,
        classification_debug: debug,
        skip: false
      })
    });
  }
}

// DIAG V2: record classification stats
(function() {
  try {
    const diagKey = 'wf2_diag_v2_' + jobId;
    const sd = $getWorkflowStaticData('global');
    if (sd[diagKey]) {
      sd[diagKey].classificationInput = (sd[diagKey].classificationInput || 0) + inputItems.length;
      sd[diagKey].supplyCount = (sd[diagKey].supplyCount || 0) + supplyCount;
      sd[diagKey].demandCount = (sd[diagKey].demandCount || 0) + kept.filter(function(k) { return k.json.candidate_class === 'DEMAND'; }).length;
      sd[diagKey].ambiguousCount = (sd[diagKey].ambiguousCount || 0) + kept.filter(function(k) { return k.json.candidate_class === 'AMBIGUOUS'; }).length;
      sd[diagKey].keepCount = (sd[diagKey].keepCount || 0) + kept.length;
      sd[diagKey].rejectCount = (sd[diagKey].rejectCount || 0) + supplyCount;
      if (!sd[diagKey].reasonCodes) sd[diagKey].reasonCodes = {};
