function normalizePhone(phone) {
  const d = phone.replace(/\D/g, '');
  if (d.length === 11 && (d[0] === '7' || d[0] === '8')) return '+7' + d.slice(1);
  if (d.length === 10) return '+7' + d;
  return '+7' + d.slice(-10);
}
function generateHash(str) {
  let hash = 0;
  for (let i = 0; i < str.length; i++) { const c = str.charCodeAt(i); hash = ((hash << 5) - hash) + c; hash = hash & hash; }
  return Math.abs(hash).toString(16);
}

const rawPhones = markdown.match(/(?:\+7|8)[\s\-\(]?\d{3}[\s\-\)]?\d{3}[\s\-]?\d{2}[\s\-]?\d{2}/g) || [];
const phones = [...new Set(rawPhones.map(normalizePhone))];
const tgMatches = markdown.match(/(?:t\.me\/|@)([a-zA-Z0-9_]{5,32})/g) || [];
const telegrams = [...new Set(tgMatches.map(function(m) { return m.startsWith('@') ? m : '@' + m.replace('t.me/', ''); }))];
