const budgets = markdown.match(/(\d{1,3}(?:[\s\.,]?\d{3})*)\s*(?:руб|₽|тыс|к\b|млн)/gi) || [];
const description = markdown.slice(0, 500);
const contactString = phones.join('') + telegrams.join('') + emails.join('');
const dedup_hash = generateHash(contactString + title);

